WITH exploded AS (SELECT id, effective_from, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS val) SELECT *, SUM(val) OVER (PARTITION BY currency) AS currency_sum_val, CUME_DIST() OVER (PARTITION BY MONTH(effective_from), currency ORDER BY val DESC) AS val_cume_dist, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY val DESC NULLS LAST) AS val_percent_rank FROM exploded
